code='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in comp); r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp); c1 = max(x for y, x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = all(grid[y][x] == color for y in range(r0, r1+1) for x in range(c0, c1+1)
                            if y in (r0, r1) or x in (c0, c1))
            if perimeter:
                frames.append((r0, r1, c0, c1, color))
    patterned = []
    for f in frames:
        r0, r1, c0, c1, color = f
        mask = [[grid[y][x] == color for x in range(c0+1, c1)] for y in range(r0+1, r1)]
        if any(any(row) for row in mask):
            patterned.append((len(mask)*len(mask[0]), f, mask))
    if not patterned:
        return out
    _, source, mask = max(patterned, key=lambda item: item[0])
    sh, sw = len(mask), len(mask[0])
    for r0, r1, c0, c1, color in frames:
        ih, iw = r1-r0-1, c1-c0-1
        if (ih, iw) != (sh, sw):
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    if out[y][x] == color:
                        out[y][x] = 0
        else:
            for i in range(ih):
                for j in range(iw):
                    out[r0+1+i][c0+1+j] = color if mask[i][j] else 0
    return out
'''
